import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CNQbXYGB.js";const x=JSON.parse('{"title":"实验 6：Triton GEMM（tl.dot）vs rocBLAS 与 hipprof 根因破案","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab06-triton-gemm-vs-rocblas.md","filePath":"labs/lab06-triton-gemm-vs-rocblas.md"}'),c={name:"labs/lab06-triton-gemm-vs-rocblas.md"};function i(n,t,l,g,a,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="实验-6-triton-gemm-tl-dot-vs-rocblas-与-hipprof-根因破案" tabindex="-1">实验 6：Triton GEMM（<code>tl.dot</code>）vs <code>rocBLAS</code> 与 <code>hipprof</code> 根因破案 <a class="header-anchor" href="#实验-6-triton-gemm-tl-dot-vs-rocblas-与-hipprof-根因破案" aria-label="Permalink to &quot;实验 6：Triton GEMM（`tl.dot`）vs `rocBLAS` 与 `hipprof` 根因破案&quot;">​</a></h1><blockquote><p><strong>源码：</strong> <a href="https://github.com/mantuoluozk/dcu-microarch-guide/blob/main/experiments/advanced/08_triton_gemm_mmac.py" target="_blank" rel="noreferrer">08_triton_gemm_mmac.py</a><br><strong>关联章节：</strong> <a href="./../02-compute/cu-and-simt.html">第 2 章：MMAC 矩阵引擎</a> &amp; <a href="./../03-memory/memory-hierarchy.html">第 3 章：<code>s_waitcnt</code> 异步流水</a></p></blockquote><hr><h2 id="_1-实验设计" tabindex="-1">1. 实验设计 <a class="header-anchor" href="#_1-实验设计" aria-label="Permalink to &quot;1. 实验设计&quot;">​</a></h2><p>在 <code>4096 × 4096 × 4096</code> FP16 矩阵乘（总计算量 <code>137.44 GFLOPs</code>）上，对比 <code>torch.matmul</code>（底层 rocBLAS）与不同 <code>(BLOCK_M, BLOCK_N, BLOCK_K, num_warps, num_stages)</code> 配置的 Triton GEMM，并用 <code>hipprof --pmc --pmc-type 3</code> 抓取硬件计数器定位差距根因。</p><hr><h2 id="_2-bw100-实测算力与静态资源对比" tabindex="-1">2. BW100 实测算力与静态资源对比 <a class="header-anchor" href="#_2-bw100-实测算力与静态资源对比" aria-label="Permalink to &quot;2. BW100 实测算力与静态资源对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实现 / 配置</th><th style="text-align:right;">耗时 (ms)</th><th style="text-align:right;">算力 (TFLOPS)</th><th style="text-align:right;">LDS (B)</th><th style="text-align:right;">VGPR / SGPR</th><th style="text-align:right;"><code>matrix_ops</code></th><th style="text-align:right;"><code>s_waitcnt</code></th></tr></thead><tbody><tr><td><strong><code>torch.matmul</code> (rocBLAS)</strong></td><td style="text-align:right;"><strong><code>0.535</code></strong></td><td style="text-align:right;"><strong><code>256.80</code></strong></td><td style="text-align:right;">-</td><td style="text-align:right;">-</td><td style="text-align:right;">-</td><td style="text-align:right;">-</td></tr><tr><td>Triton (<code>BM=128, BN=128, BK=32, w=4, s=1</code>)</td><td style="text-align:right;"><code>1.416</code></td><td style="text-align:right;"><strong><code>97.08</code></strong></td><td style="text-align:right;"><code>8704</code></td><td style="text-align:right;"><code>143 / 27</code></td><td style="text-align:right;"><code>32</code></td><td style="text-align:right;"><code>27</code></td></tr><tr><td>Triton (<code>BM=128, BN=128, BK=32, w=4, s=2</code>)</td><td style="text-align:right;"><code>1.500</code></td><td style="text-align:right;"><code>91.61</code></td><td style="text-align:right;"><code>16384</code></td><td style="text-align:right;"><code>160 / 36</code></td><td style="text-align:right;"><code>64</code></td><td style="text-align:right;"><code>32</code></td></tr><tr><td>Triton (<code>BM=128, BN=128, BK=64, w=8, s=2</code>)</td><td style="text-align:right;"><code>2.465</code></td><td style="text-align:right;"><code>55.76</code></td><td style="text-align:right;"><code>32768</code></td><td style="text-align:right;"><code>128 / 44</code></td><td style="text-align:right;"><code>64</code></td><td style="text-align:right;"><code>56</code></td></tr><tr><td>Triton (<code>BM=128, BN=256, BK=32, w=8, s=2</code>)</td><td style="text-align:right;"><code>2.566</code></td><td style="text-align:right;"><code>53.56</code></td><td style="text-align:right;"><code>24576</code></td><td style="text-align:right;"><code>128 / 44</code></td><td style="text-align:right;"><code>64</code></td><td style="text-align:right;"><code>65</code></td></tr></tbody></table><hr><h2 id="_3-hipprof-pmc-硬件计数器破案-为什么-triton-慢-4-8x" tabindex="-1">3. <code>hipprof</code> PMC 硬件计数器破案（为什么 Triton 慢 4.8x？） <a class="header-anchor" href="#_3-hipprof-pmc-硬件计数器破案-为什么-triton-慢-4-8x" aria-label="Permalink to &quot;3. `hipprof` PMC 硬件计数器破案（为什么 Triton 慢 4.8x？）&quot;">​</a></h2><p>通过 <code>hipprof --pmc --pmc-type 3 -o prof_out/exp08 python3 advanced/08_triton_gemm_mmac.py</code> 抓包，拿到 <code>rocBLAS</code>（<code>Cijk_Ailk_Bljk_HBH_MT256x256x16...</code>）与 Triton <code>gemm_kernel</code>（<code>BM=128, BN=256, BK=32</code>）的硬件级对账单：</p><table tabindex="0"><thead><tr><th>关键硬件 PMC 指标</th><th style="text-align:right;"><code>rocBLAS</code> (<code>MT256x256x16</code>)</th><th style="text-align:right;">Triton <code>gemm_kernel</code></th><th>诊断结论</th></tr></thead><tbody><tr><td>平均耗时</td><td style="text-align:right;"><strong><code>530.78 us</code></strong></td><td style="text-align:right;"><code>2556.83 us</code></td><td>慢 <code>4.82x</code></td></tr><tr><td>VGPR / SGPR</td><td style="text-align:right;"><code>212 / 112</code></td><td style="text-align:right;"><code>128 / 48</code></td><td>-</td></tr><tr><td><strong>寄存器溢出 (<code>Scratch</code>)</strong></td><td style="text-align:right;"><strong><code>0 B</code></strong></td><td style="text-align:right;"><strong><code>96 B</code>（发生 Spill！）</strong></td><td><strong>Triton 产生了 96B/thread 显存栈溢出</strong></td></tr><tr><td>全局读指令 (<code>SQ_INSTS_VMEM_RD</code>)</td><td style="text-align:right;"><strong><code>1,048,576</code></strong></td><td style="text-align:right;"><code>8,429,568</code></td><td>Triton 多发射了 <strong>8x</strong> 全局加载指令</td></tr><tr><td>LDS 指令 (<code>SQ_INSTS_LDS</code>)</td><td style="text-align:right;"><strong><code>4,194,304</code></strong></td><td style="text-align:right;"><code>21,266,432</code></td><td>Triton 多做了 <strong>5x</strong> LDS 读写</td></tr><tr><td><strong><code>SQ_LDS_BANK_CONFLICT</code></strong></td><td style="text-align:right;"><code>8,388,608</code></td><td style="text-align:right;"><strong><code>34,078,720</code></strong></td><td>Triton LDS 冲突是 <code>rocBLAS</code> 的 <strong>4.06x</strong></td></tr><tr><td><strong><code>SQ_WAIT_INST_LDS</code></strong></td><td style="text-align:right;"><strong><code>3,934,304</code></strong></td><td style="text-align:right;"><strong><code>99,050,034</code></strong></td><td><strong>Triton 有 9900 万周期卡在等 LDS（25.2x）！</strong></td></tr><tr><td>L2 命中率 (<code>TCC_HIT %</code>)</td><td style="text-align:right;"><code>81.82%</code></td><td style="text-align:right;"><strong><code>91.17%</code></strong></td><td><code>GROUP_M=8</code> 的 L2 Swizzle 非常有效</td></tr></tbody></table><p><strong>破案总结：</strong></p><ol><li>L2 命中率（<code>91.17%</code>）证明外部访存并不是瓶颈。</li><li>Triton 慢的真正元凶是：<strong><code>96 B</code> 寄存器 Spill</strong>、<strong>8 倍 <code>VMEM_RD</code> 指令</strong>，以及 <strong>高达 9900 万周期的 <code>SQ_WAIT_INST_LDS</code>（5 倍 LDS 指令 + 4 倍 Bank Conflict）</strong>。</li><li>从 <code>rocBLAS</code> 的 Kernel 名 <code>MT256x256x16</code> 可以看出：在 BW100 上采用 <strong><code>BK=16</code>（小 K 步长降低 LDS/VGPR 压力）+ <code>kpack</code> / <code>waves_per_eu</code> 调优</strong>，是下一步把 Triton GEMM 拉高到 180+ TFLOPS 的关键方向。</li></ol>',14)])])}const _=e(c,[["render",i]]);export{x as __pageData,_ as default};
